\begin{figure}[h!]
    \centering
    \includegraphics[width=0.6\textwidth]{figs/plain.pdf}
    \caption{The region of interest in the parameter space of axion mass $m_{\rm{a}}$ and coupling to photons $\ga$. In grey we show the existing bounds reproduced from the repository~\cite{ciaran_o_hare_2020_3932430}, which include: the CAST helioscope~\cite{CAST:2017uph} (shaded gray), the non-observation of $\gamma$-rays from axions produced in the SN1987A that convert to photons in the galactic magnetic field~\cite{Hoof:2022xbe} (solid dark gray), the non-observation of X-rays from axions produced in stars that convert to photons in the galactic magnetic field~\cite{Dessert:2020lil} (solid gray), and the absence of spectral distortions in the X-ray spectra of cluster-hosted quasars due to photon-axion conversion~\cite{Reynolds:2019uqt} (solid light gray). Note that Ref.~\cite{Ning:2024eky} recently placed a limit comparable to the NCG 1275 line from the non-observation of X-rays from stellar axions produced in M82 and M87 which is not shown here. The blue shaded region represents the parameters excluded at $99\%$ confidence level from requiring that the CMB spectral distortions from photon-axion conversion inside halos is compatible with the COBE/FIRAS measurements~\cite{1996ApJ...473..576F}, using the optical depth described in Sec.~\ref{sec:skyopticaldepth} (see Eq.~\eqref{eq:monopole}) and a $\chi^2$-squared test identical to what was implemented in~\citetalias{Pirvu:2023lch}.}\label{fig:bounds_and_FIRAS}
\end{figure}
================================================================================
\begin{figure}[!]
    \centering
    \includegraphics[width=0.75\textwidth]{figs/gas_contoursPlanck.pdf}
    \caption{Forecasted sensitivity to the axion-photon coupling for Planck CMB measurements and the unWISE blue galaxy sample. The $\ev{T^{\asc} T^{\asc}}$ (blue dashed) and $\ev{B^{\asc} B^{\asc}}$ (orange dashed-dotted) sensitivities are obtained from Eq.~\eqref{eq:sigma_XX} for $X=T$ and $X=B$, respectively. The strongest sensitivity is from $\ev{T^{\asc} g}$ (solid green), which is obtained from Eq.~\eqref{eq:sigma_Tg}. We also show the three point function (pink dotted) between CMB $B$-modes and the unWISE template for central galaxies, from Eq.~\eqref{eq:sigma_BBg}. For both observables involving polarization fields, the coloured shaded band shows the effect of varying the magnetic domain size $r_{\dom}$ between $1$ and $10$ kpc, and the central line corresponds to $5$ kpc. The bump in the orange and pink contours around $m_\asc \approx 8 \times 10^{-13}$ eV is due to jumps in the magnetic field amplitude between discrete and wide bins in halo mass at a redshift $z\approx 1.3$; the effect does not appear in all the observables due to different weightings of each halo contribution in each case. Existing bounds on the photon-axion coupling (all in gray) are also shown and described in Fig.~\ref{fig:bounds_and_FIRAS}.} \label{fig:Planck_sensitivity_plot}

    \includegraphics[width=0.75\textwidth]{figs/gas_contoursCMBS4.pdf}
    \caption{Same as Fig.~\ref{fig:Planck_sensitivity_plot}, but assuming CMB-S$4$ measurements and the unWISE blue galaxy sample. The lower CMB instrumental noise level and higher angular resolution translate into an improved sensitivity by a factor of $\mathcal{O}(10)$ compared to the Planck forecast, with a similar hierarchy between different observables.}\label{fig:S4_sensitivity_plot}
\end{figure}
================================================================================
\begin{figure}[h!]
    \centering
    \includegraphics[width=1\textwidth]{figs/massless_axion.pdf}
    \caption{Projected sensitivity of axion-induced screening to the combination of axion-photon coupling $\ga/{10^{-10} {\rm GeV}^{-1}}$ and the extra-galactic magnetic field $|\mathbf{B}|/{\rm nG}$ in the simple sharp boundary model (see equation~\eqref{eq:masslessaxion}), assuming Planck (left) and CMB-S4 (right) sensitivity and the unWISE blue galaxy sample. The blue solid (orange-dashed) line is the projected sensitivity with temperature auto-correlation (cross-correlation with unWISE galaxies) assuming $r_b = 5 R_{\rm vir}$, while the shaded band is obtained for $r_b$ in the range $ (R_{\rm vir} ,  10 R_{\rm vir})$. The magnetic domain size is fixed at $r_{\dom} = 1\,{\rm Mpc}$ in the IGM and the effective electron density in the IGM $n_e = m_e m_{\gamma, \rm eff}^2/e^2$ is a free parameter, as in Ref.~\cite{Mirizzi:2005ng}. The region above the black solid line is excluded from the analysis of COBE/FIRAS data  in~\cite{Mirizzi:2005ng}.}\label{fig:massless_axion.pdf}
\end{figure}
================================================================================

