import fitz, numpy as np
d = fitz.open('eprint/figs/plain.pdf')
p = d[0]
for dr in p.get_drawings():
    if dr['fill'] and abs(dr['fill'][2]-0.882)<0.01 and abs(dr['fill'][0]-0.255)<0.01:
        pts=[]
        for it in dr['items']:
            if it[0]=='l':
                pts.append((it[1].x,it[1].y)); pts.append((it[2].x,it[2].y))
            elif it[0]=='c':
                for q in it[1:]:
                    pts.append((q.x,q.y))
        pts=np.array(pts)
        # dedupe consecutive
        keep=[0]
        for i in range(1,len(pts)):
            if np.hypot(*(pts[i]-pts[keep[-1]]))>1e-6: keep.append(i)
        pts=pts[keep]
        print(len(pts))
        np.save('blue.npy', pts)
        print('x range', pts[:,0].min(), pts[:,0].max())
        print('y range', pts[:,1].min(), pts[:,1].max())
        for a,b in pts[:20]: print(round(a,2),round(b,2))
